from pathlib import Path
r=Path('opsagent-ts')
def w(p,s):
 p=r/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf8')
w('apps/console/app/api/[...path]/route.ts',r'''import {NextResponse} from 'next/server';
import {z} from 'zod';
import {readFile} from 'node:fs/promises';
import {resolve,relative} from 'node:path';
import {query,transaction,projectRoot,env} from '@opsagent/db';
import {encryptSecret,audit,hash} from '@opsagent/db/security';
import {createRun,respond,providerAvailable,employeeSchema} from '@opsagent/core';
import {organization} from '../../../lib/auth';
export const dynamic='force-dynamic';
export const runtime='nodejs';
const uuid=z.string().uuid();
const failure=(e:unknown)=>NextResponse.json({error:e instanceof Error?e.message:'Request failed'},{status:400});
export async function GET(request:Request,{params}:{params:Promise<{path:string[]}>}){const org=await organization();const {path}=await params;const [resource,id,part]=path;try{
if(resource==='runs'&&id){uuid.parse(id);const [run]=await query('SELECT * FROM platform.runs WHERE org_id=$1 AND id=$2',[org.org_id,id]);if(!run)return NextResponse.json({error:'Run not found'},{status:404});
if(part==='events'){const after=Number(new URL(request.url).searchParams.get('after'))||0;let cursor=after;const encoder=new TextEncoder();let closed=false;const stream=new ReadableStream<Uint8Array>({async start(controller){const end=Date.now()+55000;while(Date.now()<end&&!request.signal.aborted&&!closed){const rows=await query<{id:number;kind:string;payload:unknown}>('SELECT id,kind,payload FROM platform.run_events WHERE org_id=$1 AND run_id=$2 AND id>$3 ORDER BY id LIMIT 100',[org.org_id,id,cursor]);for(const row of rows){cursor=row.id;controller.enqueue(encoder.encode(`id: ${row.id}\ndata: ${JSON.stringify(row)}\n\n`));}if(!rows.length)controller.enqueue(encoder.encode(': heartbeat\n\n'));await new Promise(r=>setTimeout(r,1000));}if(!closed)controller.close();},cancel(){closed=true;}});return new Response(stream,{headers:{'Content-Type':'text/event-stream','Cache-Control':'no-cache, no-transform','X-Accel-Buffering':'no'}});}
const [steps,approvals,questions,events]=await Promise.all([query('SELECT * FROM platform.run_steps WHERE org_id=$1 AND run_id=$2 ORDER BY index',[org.org_id,id]),query('SELECT * FROM platform.approvals WHERE org_id=$1 AND run_id=$2 ORDER BY created_at',[org.org_id,id]),query('SELECT * FROM platform.questions WHERE org_id=$1 AND run_id=$2 ORDER BY created_at',[org.org_id,id]),query('SELECT * FROM platform.run_events WHERE org_id=$1 AND run_id=$2 ORDER BY id',[org.org_id,id])]);
if(part==='report'){const report=run.report as Record<string,unknown>|null;return new Response(`# OpsAgent run ${id}\n\nTask: ${run.task}\nStatus: ${run.status}\n\n\`\`\`json\n${JSON.stringify(report,null,2)}\n\`\`\`\n`,{headers:{'Content-Type':'text/markdown','Content-Disposition':`attachment; filename="run-${id}.md"`}});}
if(part==='trace')return new Response(JSON.stringify({run,steps,approvals,questions,events},null,2),{headers:{'Content-Type':'application/json','Content-Disposition':`attachment; filename="trace-${id}.json"`}});
return NextResponse.json({run,steps,approvals,questions,events});}
if(resource==='artifacts'&&id){uuid.parse(id);const [run]=await query('SELECT id FROM platform.runs WHERE org_id=$1 AND id=$2',[org.org_id,id]);if(!run)return new Response('Not found',{status:404});const file=path.slice(2).join('/');if(!/^(actor|verifier)\/screen-\d+\.png$/.test(file))return new Response('Forbidden',{status:403});const base=resolve(projectRoot,'artifacts/runs',id),target=resolve(base,file);if(relative(base,target).startsWith('..'))return new Response('Forbidden',{status:403});return new Response(new Uint8Array(await readFile(target)),{headers:{'Content-Type':'image/png','Cache-Control':'private,max-age=60'}});}
return NextResponse.json({error:'Not found'},{status:404});}catch(e){return failure(e);}}
export async function POST(request:Request,{params}:{params:Promise<{path:string[]}>}){const org=await organization();const origin=request.headers.get('origin');if(origin&&origin!==new URL(request.url).origin&&origin!==new URL(env.CONSOLE_URL).origin)return new Response('Origin rejected',{status:403});const {path}=await params;const [resource,id,part]=path;try{const body=await request.json() as unknown;
if(resource==='runs'&&!id){const input=z.object({task:z.string().min(3).max(5000),employeeId:uuid,chaos:z.boolean().default(false)}).parse(body);if(!providerAvailable())return NextResponse.json({error:'Configure the provider API key before autonomous execution.'},{status:503});await query("UPDATE mock_portal.settings SET value=$1 WHERE key='chaos'",[JSON.stringify(input.chaos)]);return NextResponse.json({id:await createRun(org.org_id,input.employeeId,input.task)});}
if(['approval','question'].includes(resource)){uuid.parse(id);const input=z.object({answer:z.string().min(1).max(5000),comment:z.string().max(2000).default('')}).parse(body);if(resource==='approval')z.enum(['approve','reject']).parse(input.answer);await respond(org.org_id,id,resource as 'approval'|'question',input.answer,input.comment);return NextResponse.json({ok:true});}
if(resource==='runs'&&part==='cancel'){uuid.parse(id);await transaction(async c=>{const rows=(await c.query('UPDATE platform.runs SET status=$1,updated_at=now() WHERE org_id=$2 AND id=$3 AND status NOT IN ($4,$5,$6,$7) RETURNING id',['CANCELLED',org.org_id,id,'COMPLETED','FAILED','ESCALATED','CANCELLED'])).rows;if(!rows.length)throw Error('Run cannot be cancelled');await c.query('UPDATE platform.approvals SET status=$1 WHERE org_id=$2 AND run_id=$3 AND status=$4',['CANCELLED',org.org_id,id,'PENDING']);await c.query('UPDATE platform.questions SET status=$1 WHERE org_id=$2 AND run_id=$3 AND status=$4',['CANCELLED',org.org_id,id,'PENDING']);});await audit(org.org_id,'operator','run.cancelled',id,{});return NextResponse.json({ok:true});}
if(resource==='employees'&&!part){const input=z.object({name:z.string().min(2).max(100),role_prompt:z.string().min(10).max(10000),allowed_tools:employeeSchema.shape.allowed_tools,policies:employeeSchema.shape.policies,connectors:employeeSchema.shape.connectors,model:z.string().nullable()}).parse(body);let employeeId=id;if(id){uuid.parse(id);const rows=await query('UPDATE platform.ai_employees SET name=$1,role_prompt=$2,allowed_tools=$3,policies=$4,connectors=$5,model=$6 WHERE org_id=$7 AND id=$8 RETURNING id',[input.name,input.role_prompt,JSON.stringify(input.allowed_tools),JSON.stringify(input.policies),JSON.stringify(input.connectors),input.model,org.org_id,id]);if(!rows.length)throw Error('Employee not found');}else{const [row]=await query<{id:string}>('INSERT INTO platform.ai_employees(org_id,name,role_prompt,allowed_tools,policies,connectors,model) VALUES($1,$2,$3,$4,$5,$6,$7) RETURNING id',[org.org_id,input.name,input.role_prompt,JSON.stringify(input.allowed_tools),JSON.stringify(input.policies),JSON.stringify(input.connectors),input.model]);employeeId=row.id;}await audit(org.org_id,'operator','employee.saved',employeeId!,{name:input.name});return NextResponse.json({id:employeeId});}
if(resource==='employees'&&id){uuid.parse(id);const [employee]=await query('SELECT id FROM platform.ai_employees WHERE org_id=$1 AND id=$2',[org.org_id,id]);if(!employee)throw Error('Employee not found');
if(part==='credentials'){const input=z.object({handle:z.string().regex(/^[a-z0-9_-]{1,80}$/i),username:z.string().min(1).max(200),password:z.string().min(1).max(200)}).parse(body);const encrypted=encryptSecret(JSON.stringify({username:input.username,password:input.password}),`${org.org_id}:${id}:${input.handle}`);await query('INSERT INTO platform.credentials(org_id,employee_id,handle,ciphertext) VALUES($1,$2,$3,$4) ON CONFLICT(org_id,employee_id,handle) DO UPDATE SET ciphertext=EXCLUDED.ciphertext',[org.org_id,id,input.handle,encrypted]);await audit(org.org_id,'operator','credential.configured',id,{handle:input.handle});return NextResponse.json({ok:true});}
if(part==='knowledge'){const input=z.object({id:uuid.optional(),title:z.string().min(1).max(100),content:z.string().min(1).max(100000)}).parse(body);await transaction(async c=>{let docId=input.id;if(docId){const rows=(await c.query('UPDATE platform.knowledge_docs SET title=$1,content=$2 WHERE id=$3 AND org_id=$4 AND employee_id=$5 RETURNING id',[input.title,input.content,docId,org.org_id,id])).rows;if(!rows.length)throw Error('Document not found');await c.query('DELETE FROM platform.knowledge_chunks WHERE doc_id=$1 AND org_id=$2',[docId,org.org_id]);}else{docId=(await c.query<{id:string}>('INSERT INTO platform.knowledge_docs(org_id,employee_id,title,content) VALUES($1,$2,$3,$4) RETURNING id',[org.org_id,id,input.title,input.content])).rows[0].id;}const chunks=input.content.match(/[\s\S]{1,4000}/g)||[];for(const content of chunks)await c.query('INSERT INTO platform.knowledge_chunks(org_id,employee_id,doc_id,content) VALUES($1,$2,$3,$4)',[org.org_id,id,docId,content]);});await audit(org.org_id,'operator','knowledge.saved',id,{title:input.title,contentHash:hash(input.content)});return NextResponse.json({ok:true});}}
if(resource==='lessons'&&id){uuid.parse(id);const input=z.object({content:z.string().max(500),remove:z.boolean().default(false)}).parse(body);if(input.remove)await query('DELETE FROM platform.lessons WHERE id=$1 AND org_id=$2',[id,org.org_id]);else await query('UPDATE platform.lessons SET content=$1 WHERE id=$2 AND org_id=$3',[input.content,id,org.org_id]);await audit(org.org_id,'operator','lesson.edited',id,{remove:input.remove});return NextResponse.json({ok:true});}
return NextResponse.json({error:'Not found'},{status:404});}catch(e){return failure(e);}}
''')
w('apps/console/components/human-card.tsx',r''' 'use client';
import {useState} from 'react';
import {Button} from './ui/button';
import {Card} from './ui/card';
import {Badge} from './ui/badge';
export type Approval={id:string;run_id:string;status:string;reason:string;citation:string;action:unknown};
export type Question={id:string;run_id:string;status:string;question:string;answer?:string};
export function HumanCard({approval,question,onDone}:{approval?:Approval;question?:Question;onDone?:()=>void}){const [text,setText]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);const item=approval||question;if(!item)return null;async function reply(answer:string){setBusy(true);try{const r=await fetch(`/api/${approval?'approval':'question'}/${item!.id}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({answer,comment:approval?text:''})});if(!r.ok)throw Error((await r.json() as {error:string}).error);onDone?.();}catch(e){setError(String(e));}finally{setBusy(false);}}return <Card className={approval?'approval':'question'}><div className="row mb-3"><Badge tone={approval?'blue':'amber'}>{approval?'APPROVAL REQUIRED':'INPUT REQUIRED'}</Badge><a className="muted text-xs" href={'/runs/'+item.run_id}>Open run →</a></div><h2>{approval?'Review this exact action':'Your employee needs an answer'}</h2>{approval?<><p>{approval.reason}</p><small>{approval.citation}</small><pre>{JSON.stringify(approval.action,null,2)}</pre></>:<p>{question!.question}</p>}{item.status==='PENDING'?<><label className="field mt-4"><span>{approval?'Optional review comment':'Your answer'}</span><textarea aria-label={approval?'Approval comment':'Human answer'} value={text} onChange={e=>setText(e.target.value)} rows={2}/></label><div className="actions">{approval?<><Button disabled={busy} onClick={()=>void reply('approve')}>Approve action</Button><Button variant="destructive" disabled={busy} onClick={()=>void reply('reject')}>Reject</Button></>:<Button disabled={busy||!text.trim()} onClick={()=>void reply(text)}>Send answer</Button>}</div></>:<Badge tone="green">{item.status}</Badge>}{error&&<p className="error-text">{error}</p>}</Card>}
''')
w('apps/console/components/run-view.tsx',r''' 'use client';
import {useCallback,useEffect,useState} from 'react';
import {Card} from './ui/card';
import {Badge} from './ui/badge';
import {Button} from './ui/button';
import {HumanCard,type Approval,type Question} from './human-card';
type Snapshot={run:{id:string;task:string;status:string;checkpoint:{spec?:{outcome:string;criteria:string[];policies:{rule:string;citation:string}[]};plan?:string[];steps:number;tokens:number;cost:number;recoveries:number};report?:{verification:{status:string;criteria?:{criterion:string;passed:boolean;evidence:string}[];reason?:string};metrics:unknown}};steps:{id:string;index:number;tool:string;args:unknown;result:unknown;screenshot?:string;latency:number;error_type?:string}[];events:{id:number;kind:string;payload:unknown}[];approvals:Approval[];questions:Question[]};
export function RunView({id}:{id:string}){const [data,setData]=useState<Snapshot>(),[error,setError]=useState('');const reload=useCallback(async()=>{try{const r=await fetch('/api/runs/'+id);if(!r.ok)throw Error('Unable to load run');setData(await r.json() as Snapshot);}catch(e){setError(String(e));}},[id]);useEffect(()=>{void reload();let cursor=0;let source:EventSource|undefined;let timer:ReturnType<typeof setTimeout>|undefined;let disposed=false;function connect(){if(disposed)return;source=new EventSource(`/api/runs/${id}/events?after=${cursor}`);source.onmessage=e=>{const event=JSON.parse(e.data) as {id:number};cursor=event.id;void reload();};source.onerror=()=>{source?.close();timer=setTimeout(connect,1500);};}connect();return()=>{disposed=true;source?.close();if(timer)clearTimeout(timer);};},[id,reload]);if(!data)return <Card>{error||'Loading operation…'}</Card>;const {run,steps,approvals,questions,events}=data,cp=run.checkpoint;const latest=steps.filter(s=>s.screenshot).at(-1);const report=run.report;return <><div className="page-heading"><div><span className="eyebrow">OPERATION {id.slice(0,8)}</span><h1 className="text-2xl">{run.task}</h1><p className="muted">Every decision, action, and recovery is persisted.</p></div><Badge tone={run.status==='COMPLETED'?'green':run.status.startsWith('AWAITING')?'amber':'blue'}>{run.status.replaceAll('_',' ')}</Badge></div><div className="state-strip">{['QUEUED','UNDERSTANDING','PLANNING','EXECUTING','AWAITING_APPROVAL','AWAITING_INPUT','VERIFYING','COMPLETED'].map(s=><span className={'state-dot '+(s===run.status?'active':'')} key={s}>{s.replaceAll('_',' ')}</span>)}</div><div className="run-grid"><div className="stack">{approvals.filter(a=>a.status==='PENDING').map(a=><HumanCard key={a.id} approval={a} onDone={()=>void reload()}/>)}{questions.filter(q=>q.status==='PENDING').map(q=><HumanCard key={q.id} question={q} onDone={()=>void reload()}/>)}{cp.spec&&<Card><h2>Success criteria</h2><p className="muted text-xs">{cp.spec.outcome}</p><ul className="mt-4 space-y-3">{cp.spec.criteria.map((c,i)=><li key={i} className="row"><Badge tone="blue">{i+1}</Badge><span>{c}</span></li>)}</ul><details className="mt-4"><summary className="muted text-xs">Applicable procedures</summary><pre>{JSON.stringify(cp.spec.policies,null,2)}</pre></details></Card>}<Card><h2>Execution timeline <span className="muted text-xs ml-2">{steps.length} steps</span></h2>{!steps.length&&<p className="muted">Waiting for the worker’s next checkpoint.</p>}{steps.map(s=><div className={'step '+(s.error_type?'recovery':'')} key={s.id}><div className="step-head"><strong>{s.index}. {s.tool}</strong><span className="muted">{s.latency} ms {s.error_type&&<Badge tone="amber">{s.error_type}</Badge>}</span></div><details><summary>Arguments and observed result</summary><pre>{JSON.stringify({args:s.args,result:s.result},null,2)}</pre></details></div>)}{events.filter(e=>['policy','recovery','verification'].includes(e.kind)).map(e=><div key={e.id} className={'step '+e.kind}><div className="step-head"><Badge tone={e.kind==='recovery'?'amber':'blue'}>{e.kind.toUpperCase()}</Badge></div><details><summary>Evidence</summary><pre>{JSON.stringify(e.payload,null,2)}</pre></details></div>)}</Card>{report&&<Card><div className="row mb-4"><h2 className="mb-0">Independent verification</h2><Badge tone={report.verification.status==='VERIFIED'?'green':report.verification.status==='PARTIAL'?'amber':'red'}>{report.verification.status}</Badge></div>{report.verification.reason&&<p>{report.verification.reason}</p>}{report.verification.criteria?.map((c,i)=><div className="mt-4" key={i}><div className="row"><Badge tone={c.passed?'green':'red'}>{c.passed?'PASS':'FAIL'}</Badge><strong>{c.criterion}</strong></div><details className="mt-2"><summary className="muted text-xs">Fresh evidence</summary><pre>{c.evidence}</pre></details></div>)}<div className="actions mt-5"><a href={'/api/runs/'+id+'/report'}><Button variant="outline" size="sm">Export report</Button></a><a href={'/api/runs/'+id+'/trace'}><Button variant="outline" size="sm">Download trace JSON</Button></a></div></Card>}</div><div className="stack"><Card><h2>Run budget</h2><div className="grid grid-cols-2 gap-5"><div><small>Steps</small><strong>{cp.steps} / 60</strong></div><div><small>Tokens</small><strong>{cp.tokens.toLocaleString()}</strong></div><div><small>Estimated cost</small><strong>${cp.cost.toFixed(4)}</strong></div><div><small>Recoveries</small><strong>{cp.recoveries}</strong></div></div></Card><Card><h2>Current plan</h2><ol className="space-y-4">{cp.plan?.map((p,i)=><li key={i} className="row"><Badge>{i+1}</Badge><span>{p}</span></li>)||<p className="muted">Plan will appear after understanding.</p>}</ol></Card><Card><h2>Latest browser evidence</h2>{latest?<a href={`/api/artifacts/${id}/${latest.screenshot}`} target="_blank" rel="noreferrer"><img alt="Latest browser screenshot" className="screenshot" src={`/api/artifacts/${id}/${latest.screenshot}`}/></a>:<div className="empty">No screenshot yet.</div>}</Card>{steps.some(s=>s.screenshot)&&<Card><h2>Evidence gallery</h2><div className="grid grid-cols-2 gap-2">{steps.filter(s=>s.screenshot).map(s=><a key={s.id} href={`/api/artifacts/${id}/${s.screenshot}`} target="_blank" rel="noreferrer"><img className="screenshot" alt={'Step '+s.index} src={`/api/artifacts/${id}/${s.screenshot}`}/></a>)}</div></Card>}{!['COMPLETED','FAILED','ESCALATED','CANCELLED'].includes(run.status)&&<Button variant="destructive" onClick={async()=>{await fetch(`/api/runs/${id}/cancel`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});await reload();}}>Cancel operation</Button>}</div></div>{error&&<p className="error-text">{error}</p>}</>}
''')
w('apps/console/app/runs/[id]/page.tsx',r'''import {organization} from '../../../lib/auth';
import {Shell} from '../../../components/shell';
import {RunView} from '../../../components/run-view';
export default async function RunPage({params}:{params:Promise<{id:string}>}){await organization();return <Shell><RunView id={(await params).id}/></Shell>}
''')
w('apps/console/app/inbox/page.tsx',r'''import {query} from '@opsagent/db';
import {organization} from '../../lib/auth';
import {Shell} from '../../components/shell';
import {InboxCards} from '../../components/inbox-cards';
import type {Approval,Question} from '../../components/human-card';
export const dynamic='force-dynamic';
export default async function Inbox(){const org=await organization();const [approvals,questions]=await Promise.all([query<Approval>('SELECT * FROM platform.approvals WHERE org_id=$1 AND status=$2 ORDER BY created_at',[org.org_id,'PENDING']),query<Question>('SELECT * FROM platform.questions WHERE org_id=$1 AND status=$2 ORDER BY created_at',[org.org_id,'PENDING'])]);return <Shell><div className="page-heading"><div><span className="eyebrow">HUMAN IN THE LOOP</span><h1>Your attention, where it matters</h1><p className="muted">Review exact actions and unblock your employees.</p></div></div><InboxCards approvals={approvals} questions={questions}/></Shell>}
''')
w('apps/console/components/inbox-cards.tsx',r''' 'use client';
import {useRouter} from 'next/navigation';
import {HumanCard,type Approval,type Question} from './human-card';
import {Card} from './ui/card';
export function InboxCards({approvals,questions}:{approvals:Approval[];questions:Question[]}){const router=useRouter();return <div className="stack">{approvals.map(a=><HumanCard key={a.id} approval={a} onDone={()=>router.refresh()}/>)}{questions.map(q=><HumanCard key={q.id} question={q} onDone={()=>router.refresh()}/>)}{!approvals.length&&!questions.length&&<Card className="empty">You’re all caught up.<small>Approval requests and questions will appear here.</small></Card>}</div>}
''')
